"""Maschinencode fuer den Charm-Mod (automatisch erzeugt mit tools/dev/gen_charm_code.py).

Alle Funktionen sind Thumb-Code und liegen im ARM9 in einer ungenutzten Funktion
(Teil der printf-Bibliothek, nirgends referenziert) ab 0x02085200.
"""
CAVE_ADDR = 0x02085200
CAVE_BLOB = bytes.fromhex(
    ""
)
# SHA1 der 694 Original-Bytes an dieser Stelle (Sicherheitspruefung gegen andere ROM-Versionen)
CAVE_ORIG_SHA1 = "5caac327a06e6afbb1476794325334881d509c06"
# Charm-Items: die 17 Edelsteine (Gems), Item 548..564. Gruppen (Bit, Item-IDs):
# Bit 0 Shiny Charm (8 Items), Bit 1 100% IV Charm (4), Bit 2 Legendary Charm (3), Bit 3 Static Charm (2)
GROUPS = [(0, [548, 549, 550, 551, 552, 553, 554, 555]), (1, [556, 557, 558, 559]), (2, [560, 561, 562]), (3, [563, 564])]
# Offsets (im Blob) der 17 Item-Ladebefehle (je 6 Bytes: movs r1,#hi / lsls r1,r1,#8 / adds r1,#lo),
# in der Reihenfolge der Items in GROUPS
ITEM_LOAD_OFFSETS = (14, 32, 50, 68, 86, 104, 122, 140, 158, 178, 198, 218, 238, 258, 278, 298, 318)
# Offset (im Blob) der Fundchance "1 zu N" (Befehl "movs r0, #N"), Standard 20
FIND_RATE_OFFSET = 488
FIND_RATE_DEFAULT = 20
HELPER_ENTRY = 0x02085200
HELPER_COUNT = 0x02085394
HELPER_IV = 0x020853C8
HELPER_HOLD = 0x020853E0

# Einhaengestellen im Overlay 36 (Funktion, die wilde Pokemon fuer den Kampf erzeugt):
